update public.finance_accounts set name_my = case code
when '1000' then 'ငွေသားနှင့် ဘဏ်' when '1010' then 'ငွေသား' when '1020' then 'ဘဏ်နှင့် ပွိုင့်လက်ကျန်'
when '2000' then 'ပေးရန်ရှိငွေ' when '3000' then 'ရန်ပုံငွေလက်ကျန်'
when '4000' then 'လှူဒါန်းငွေ' when '4010' then 'အသင်းတော်နှင့် အလှူရှင်ထောက်ပံ့ငွေ' when '4020' then 'ကျောင်းလခနှင့် ကျောင်းသားပေးငွေ' when '4030' then 'အခြားဝင်ငွေ' when '4100' then 'ကျောင်းလခ'
when '5000' then 'လုပ်ငန်းကုန်ကျစရိတ်' when '5100' then 'လစဉ်ထွက်ငွေ' when '5101' then 'သင်းအုပ်နှင့် ခေါင်းဆောင်အစည်းအဝေး' when '5102' then 'ဘုရားဝတ်ပြုချိန်နှင့် သင်ကြားခ' when '5103' then 'လျှပ်စစ်မီတာခ' when '5104' then 'QT စာအုပ်' when '5105' then 'ယာဉ်ဆီဖိုး' when '5106' then 'သောက်ရေ' when '5107' then 'ဒီဇယ်ဆီ' when '5108' then 'စာကြည့်တိုက်' when '5109' then 'ကျောင်းသားခေါင်းဆောင်လှုပ်ရှားမှု' when '5110' then 'မေတ္တာဗီလာ' when '5111' then 'မီးဖိုချောင်အသုံးစရိတ်' when '5112' then 'အင်တာနက်ခ' when '5113' then 'ဆေးဝါး' when '5114' then 'ဧည့်ခံစရိတ်'
when '5200' then 'လိုအပ်သလို ထွက်ငွေ' when '5201' then 'ရေမီတာခ' when '5202' then 'ပစ္စည်းနှင့် အသုံးအဆောင်' when '5203' then 'ပြုပြင်စရိတ်' when '5204' then 'ယာယီလုပ်သားခ' when '5205' then 'မုန့်ဖိုး' when '5206' then 'အစည်းအဝေးစရိတ်' when '5207' then 'ကျောင်းသားကူညီငွေ' when '5208' then 'ကျောင်းသားသစ်ပစ္စည်း' when '5209' then 'စာအုပ်ဝယ်ယူခြင်း' when '5210' then 'အခြားထွက်ငွေ' when '5211' then 'သွားလာစရိတ်' when '5212' then 'စာသင်နှစ်ဖွင့်စရိတ်' when '5213' then 'MRPST Company' when '5214' then 'Dawn638 Company' when '5215' then 'အခွန်' when '5300' then 'ပညာသင်ဆုကုန်ကျစရိတ်' else name_my end;
